import React, { FunctionComponent } from 'react';
import classNames from 'classnames';
import Text from '../../atoms/text';
import './index.less';
import { SizeEnum, AlignEnum } from '../../types';
interface StatusMessageFooterProps {
  className?: string;
  statusMessageAction?: JSX.Element;
  statusMessageText?: JSX.Element;
  statusMessageType?: keyof typeof statusMessageTypeOptions;
  statusMessageIcon?: keyof typeof statusMessageIconOptions | string;
  statusMessageStyle?: keyof typeof statusMessageStyleOptions;
}

export const statusMessageTypeOptions = {
  confirmation: 'confirmation-type',
  error: 'error-type',
  warning: 'warning-type',
  success: 'success-style',
  undo: 'undo-type',
};

export const statusMessageStyleOptions = {
  default: '',
  wide: 'wide-style',
};

const statusMessageIconOptions = {
  check: 'icon-check',
  clock: 'icon-clock-2',
  hourglass: 'icon-hourglass-bottom',
  x: 'icon-x-2',
  none: '',
};

const StatusMessageFooter: FunctionComponent<StatusMessageFooterProps> = ({
  className,
  statusMessageAction,
  statusMessageText,
  statusMessageType = 'confirmation-type',
  statusMessageIcon = 'none',
  statusMessageStyle = 'default',
}) => {
  return (
    <div
      className={classNames(
        'status-message-footer',
        className,
        statusMessageTypeOptions[statusMessageType],
        statusMessageStyleOptions[statusMessageStyle],
      )}
    >
      <Text
        size={SizeEnum['12px']}
        className={classNames(
          'status-message-icon',
          statusMessageIconOptions[statusMessageIcon],
          statusMessageIcon,
        )}
      />
      {typeof statusMessageText === 'string' ? (
        <>
          <Text
            className="status-message-text"
            size={SizeEnum['12px']}
            align={AlignEnum.left}
            text={statusMessageText}
          />
        </>
      ) : (
        <>
          <Text className="status-message-text" size={SizeEnum['12px']} align={AlignEnum.left}>
            {statusMessageText}
          </Text>
        </>
      )}
      <div className="status-message-action">{statusMessageAction}</div>
    </div>
  );
};

export default StatusMessageFooter;
